import{i as e,r as t,s as n,t as r}from"./app-FtcyK8lR.js";var i=JSON.parse(`{"path":"/guide/ui-config/channel.html","title":"渠道管理","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1772867174000,"contributors":[{"name":"MurphyYi","username":"MurphyYi","email":"zy84338719@hotmail.com","commits":2,"url":"https://github.com/MurphyYi"}],"changelog":[{"hash":"46a94be73dccfa2afd836e97cca5b5781eccb641","time":1772867174000,"email":"zy84338719@hotmail.com","author":"MurphyYi","message":"fix: 修复文档中所有内部链接使用相对路径"},{"hash":"acf808fd844d46e164aa5b1e98e65abaf9fa76dd","time":1772854092000,"email":"zy84338719@hotmail.com","author":"MurphyYi","message":"docs: 添加完整的 UI配置流程和平台对接文档"}]},"filePathRelative":"guide/ui-config/channel.md"}`),a={name:`channel.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="渠道管理" tabindex="-1"><a class="header-anchor" href="#渠道管理">#</a> 渠道管理</h1><p>渠道（Pipeline）是虹桥计划中用于在同一环境下管理不同功能分支或版本线的概念。本指南将帮助你创建和管理渠道。</p><h2 id="概念说明" tabindex="-1"><a class="header-anchor" href="#概念说明">#</a> 概念说明</h2><h3 id="什么是渠道" tabindex="-1"><a class="header-anchor" href="#什么是渠道">#</a> 什么是渠道？</h3><p>渠道用于在同一环境下进一步细分配置，适用于以下场景：</p><table><thead><tr><th>渠道标识</th><th>说明</th><th>典型用途</th></tr></thead><tbody><tr><td><code>main</code></td><td>主渠道</td><td>正式发布的版本</td></tr><tr><td><code>hotfix</code></td><td>热修复渠道</td><td>紧急修复的版本</td></tr><tr><td><code>feature-xxx</code></td><td>功能渠道</td><td>特定功能的开发版本</td></tr><tr><td><code>experiment</code></td><td>实验渠道</td><td>A/B 测试、灰度发布</td></tr></tbody></table><h3 id="渠道与配置的关系" tabindex="-1"><a class="header-anchor" href="#渠道与配置的关系">#</a> 渠道与配置的关系</h3><p>渠道是配置的容器，每个配置都属于一个特定的环境+渠道组合：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">prod (环境)</span>
<span class="line">└── main (渠道)</span>
<span class="line">    ├── api_base_url</span>
<span class="line">    ├── theme_color</span>
<span class="line">    └── feature_flags</span>
<span class="line"></span>
<span class="line">prod (环境)</span>
<span class="line">└── hotfix (渠道)</span>
<span class="line">    ├── api_base_url      # 可以有不同的值</span>
<span class="line">    ├── theme_color</span>
<span class="line">    └── feature_flags</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="创建渠道" tabindex="-1"><a class="header-anchor" href="#创建渠道">#</a> 创建渠道</h2><h3 id="前置条件" tabindex="-1"><a class="header-anchor" href="#前置条件">#</a> 前置条件</h3><p>创建渠道前，需要先创建所属的环境。参见 <a href="./environment">环境管理</a>。</p><h3 id="通过-ui-创建" tabindex="-1"><a class="header-anchor" href="#通过-ui-创建">#</a> 通过 UI 创建</h3><ol><li>访问管理界面：<code>http://localhost:8080/rainbow-bridge</code></li><li>点击左侧导航栏的 <strong>环境管理</strong></li><li>找到目标环境，点击 <strong>管理渠道</strong> 按钮</li><li>点击 <strong>新建渠道</strong> 按钮</li><li>填写渠道信息： <ul><li><strong>渠道标识</strong>：唯一标识符，如 <code>main</code></li><li><strong>渠道名称</strong>：显示名称，如 <code>主渠道</code></li><li><strong>备注</strong>：可选，描述信息</li></ul></li><li>点击 <strong>确定</strong> 保存</li></ol><h3 id="通过-api-创建" tabindex="-1"><a class="header-anchor" href="#通过-api-创建">#</a> 通过 API 创建</h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token function">curl</span> <span class="token parameter variable">-X</span> POST http://localhost:8080/rainbow-bridge/api/v1/pipeline/create <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-H</span> <span class="token string">&quot;Content-Type: application/json&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-d</span> <span class="token string">&#39;{</span>
<span class="line">    &quot;environment_key&quot;: &quot;prod&quot;,</span>
<span class="line">    &quot;pipeline_key&quot;: &quot;hotfix&quot;,</span>
<span class="line">    &quot;pipeline_name&quot;: &quot;热修复渠道&quot;,</span>
<span class="line">    &quot;remark&quot;: &quot;生产环境热修复版本&quot;</span>
<span class="line">  }&#39;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="管理渠道" tabindex="-1"><a class="header-anchor" href="#管理渠道">#</a> 管理渠道</h2><h3 id="查看渠道列表" tabindex="-1"><a class="header-anchor" href="#查看渠道列表">#</a> 查看渠道列表</h3><p><strong>通过 UI</strong>：</p><ol><li>进入 <strong>环境管理</strong> 页面</li><li>点击环境的 <strong>管理渠道</strong> 按钮</li></ol><p><strong>通过 API</strong>：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token function">curl</span> <span class="token string">&quot;http://localhost:8080/rainbow-bridge/api/v1/pipeline/list?environment_key=prod&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="编辑渠道" tabindex="-1"><a class="header-anchor" href="#编辑渠道">#</a> 编辑渠道</h3><ol><li>在渠道列表中找到目标渠道</li><li>点击 <strong>编辑</strong> 按钮</li><li>修改渠道名称或备注</li><li>点击 <strong>确定</strong> 保存</li></ol><div class="hint-container warning"><p class="hint-container-title">注意</p><p>渠道标识（pipeline_key）创建后不可修改，只能修改渠道名称和备注。</p></div><h3 id="删除渠道" tabindex="-1"><a class="header-anchor" href="#删除渠道">#</a> 删除渠道</h3><ol><li>在渠道列表中找到目标渠道</li><li>点击 <strong>删除</strong> 按钮</li><li>确认删除操作</li></ol><div class="hint-container caution"><p class="hint-container-title">警告</p><p>删除渠道将同时删除该渠道下的所有配置，此操作不可恢复！</p></div><h2 id="渠道切换" tabindex="-1"><a class="header-anchor" href="#渠道切换">#</a> 渠道切换</h2><h3 id="运行时切换" tabindex="-1"><a class="header-anchor" href="#运行时切换">#</a> 运行时切换</h3><p>客户端通过请求头指定渠道：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 获取 prod 环境下 main 渠道的配置</span></span>
<span class="line"><span class="token function">curl</span> http://localhost:8080/rainbow-bridge/api/v1/runtime/config <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-H</span> <span class="token string">&quot;x-environment: prod&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-H</span> <span class="token string">&quot;x-pipeline: main&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 获取 prod 环境下 hotfix 渠道的配置</span></span>
<span class="line"><span class="token function">curl</span> http://localhost:8080/rainbow-bridge/api/v1/runtime/config <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-H</span> <span class="token string">&quot;x-environment: prod&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-H</span> <span class="token string">&quot;x-pipeline: hotfix&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="客户端集成" tabindex="-1"><a class="header-anchor" href="#客户端集成">#</a> 客户端集成</h3><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 获取配置时指定渠道</span></span>
<span class="line"><span class="token keyword">const</span> config <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token function">fetch</span><span class="token punctuation">(</span><span class="token string">&#39;/api/v1/runtime/config&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token literal-property property">headers</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token string-property property">&#39;x-environment&#39;</span><span class="token operator">:</span> <span class="token string">&#39;prod&#39;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token string-property property">&#39;x-pipeline&#39;</span><span class="token operator">:</span> <span class="token string">&#39;hotfix&#39;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token parameter">res</span> <span class="token operator">=&gt;</span> res<span class="token punctuation">.</span><span class="token function">json</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="最佳实践" tabindex="-1"><a class="header-anchor" href="#最佳实践">#</a> 最佳实践</h2><h3 id="渠道命名规范" tabindex="-1"><a class="header-anchor" href="#渠道命名规范">#</a> 渠道命名规范</h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line"># 推荐的命名方式</span>
<span class="line">main          - 主渠道（正式发布）</span>
<span class="line">hotfix        - 热修复渠道</span>
<span class="line">feature-xxx   - 特定功能渠道</span>
<span class="line">experiment    - 实验性功能渠道</span>
<span class="line">beta          - 公测渠道</span>
<span class="line">alpha         - 内测渠道</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="常见使用场景" tabindex="-1"><a class="header-anchor" href="#常见使用场景">#</a> 常见使用场景</h3><h4 id="场景-1-热修复发布" tabindex="-1"><a class="header-anchor" href="#场景-1-热修复发布">#</a> 场景 1：热修复发布</h4><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">生产环境配置出现问题，需要紧急修复：</span>
<span class="line"></span>
<span class="line">1. 创建 hotfix 渠道</span>
<span class="line">2. 在 hotfix 渠道中修复配置</span>
<span class="line">3. 客户端切换到 hotfix 渠道</span>
<span class="line">4. 问题解决后，同步到 main 渠道</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="场景-2-灰度发布" tabindex="-1"><a class="header-anchor" href="#场景-2-灰度发布">#</a> 场景 2：灰度发布</h4><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">新功能需要小范围测试：</span>
<span class="line"></span>
<span class="line">1. 创建 experiment 渠道</span>
<span class="line">2. 配置新功能的开关和参数</span>
<span class="line">3. 部分用户切换到 experiment 渠道</span>
<span class="line">4. 测试通过后，合并到 main 渠道</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="场景-3-多版本共存" tabindex="-1"><a class="header-anchor" href="#场景-3-多版本共存">#</a> 场景 3：多版本共存</h4><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">同时维护多个版本：</span>
<span class="line"></span>
<span class="line">prod</span>
<span class="line">├── v1 (旧版本渠道)</span>
<span class="line">├── v2 (当前版本渠道)</span>
<span class="line">└── v3 (新版本渠道)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="配置继承建议" tabindex="-1"><a class="header-anchor" href="#配置继承建议">#</a> 配置继承建议</h3><p>新渠道可以从现有渠道复制配置：</p><ol><li>使用 <a href="./migration">配置迁移</a> 功能</li><li>选择源渠道的配置复制到新渠道</li><li>修改需要差异化的配置</li></ol><h2 id="常见问题" tabindex="-1"><a class="header-anchor" href="#常见问题">#</a> 常见问题</h2><h3 id="q-渠道标识可以修改吗" tabindex="-1"><a class="header-anchor" href="#q-渠道标识可以修改吗">#</a> Q: 渠道标识可以修改吗？</h3><p>A: 不可以。渠道标识是系统的唯一标识，创建后不可修改。</p><h3 id="q-一个环境可以有多少个渠道" tabindex="-1"><a class="header-anchor" href="#q-一个环境可以有多少个渠道">#</a> Q: 一个环境可以有多少个渠道？</h3><p>A: 系统没有限制，但建议根据实际需要创建，通常不超过 5 个。</p><h3 id="q-不同渠道的配置可以不同吗" tabindex="-1"><a class="header-anchor" href="#q-不同渠道的配置可以不同吗">#</a> Q: 不同渠道的配置可以不同吗？</h3><p>A: 是的，这正是渠道的核心用途。同一配置在不同渠道可以有不同的值。</p><h3 id="q-如何实现渠道间的配置同步" tabindex="-1"><a class="header-anchor" href="#q-如何实现渠道间的配置同步">#</a> Q: 如何实现渠道间的配置同步？</h3><p>A: 使用 <a href="./migration">配置迁移</a> 功能，可以选择性复制配置到其他渠道。</p><h2 id="下一步" tabindex="-1"><a class="header-anchor" href="#下一步">#</a> 下一步</h2><ul><li><a href="./config">配置管理</a> - 学习如何创建和管理配置</li><li><a href="./resource">资源管理</a> - 了解静态资源的管理</li><li><a href="./migration">配置迁移</a> - 在渠道间迁移配置</li></ul>`,58)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};